// RegistryHeaderMagic is the offset of magic: u64 const, written by supervisor; REGISTRY_MAGIC.
const RegistryHeaderMagic = 0x0

// RegistryHeaderRegistryLen is the offset of registry_len: u32 const, written by supervisor.
const RegistryHeaderRegistryLen = 0x8

// RegistryHeaderTemplateCount is the offset of template_count: u16 const, written by supervisor.
const RegistryHeaderTemplateCount = 0xc

// RegistryHeaderTemplateStride is the offset of template_stride: u16 const, written by supervisor.
const RegistryHeaderTemplateStride = 0xe

// RegistryHeaderColumnStride is the offset of column_stride: u16 const, written by supervisor.
const RegistryHeaderColumnStride = 0x10

// RegistryHeaderPatchStride is the offset of patch_stride: u16 const, written by supervisor.
const RegistryHeaderPatchStride = 0x12

// RegistryHeaderInSchemaOff is the offset of in_schema_off: u32 const, written by supervisor; Arrow IPC Schema message for requests.
const RegistryHeaderInSchemaOff = 0x14

// RegistryHeaderInSchemaLen is the offset of in_schema_len: u32 const, written by supervisor.
const RegistryHeaderInSchemaLen = 0x18

// RegistryHeaderOutSchemaOff is the offset of out_schema_off: u32 const, written by supervisor; Arrow IPC Schema message for responses.
const RegistryHeaderOutSchemaOff = 0x1c

// RegistryHeaderOutSchemaLen is the offset of out_schema_len: u32 const, written by supervisor.
const RegistryHeaderOutSchemaLen = 0x20

// RegistryHeaderTemplatesOff is the offset of templates_off: u32 const, written by supervisor.
const RegistryHeaderTemplatesOff = 0x24

// RegistryHeaderColumnsOff is the offset of columns_off: u32 const, written by supervisor.
const RegistryHeaderColumnsOff = 0x28

// RegistryHeaderPatchesOff is the offset of patches_off: u32 const, written by supervisor.
const RegistryHeaderPatchesOff = 0x2c

// RegistryHeaderNamesOff is the offset of names_off: u32 const, written by supervisor.
const RegistryHeaderNamesOff = 0x30

// RegistryHeaderNamesLen is the offset of names_len: u32 const, written by supervisor.
const RegistryHeaderNamesLen = 0x34

// RegistryHeaderColumnTotal is the offset of column_total: u32 const, written by supervisor; ColumnDesc entries, over all templates.
const RegistryHeaderColumnTotal = 0x38

// RegistryHeaderPatchTotal is the offset of patch_total: u32 const, written by supervisor; PatchDesc entries, over all templates.
const RegistryHeaderPatchTotal = 0x3c

// Region template_desc (segment: registry).
const TemplateDescSize = 0x30

// TemplateDescTemplateId is the offset of template_id: u16 const, written by supervisor; never 0.
const TemplateDescTemplateId = 0x0

// TemplateDescDirection is the offset of direction: u8 const, written by supervisor.
const TemplateDescDirection = 0x2

// TemplateDescFlags is the offset of flags: u8 const, written by supervisor.
const TemplateDescFlags = 0x3

// TemplateDescSlabClass is the offset of slab_class: u16 const, written by supervisor.
const TemplateDescSlabClass = 0x4

// TemplateDescColumnCount is the offset of column_count: u16 const, written by supervisor.
const TemplateDescColumnCount = 0x6

// TemplateDescMaxRows is the offset of max_rows: u32 const, written by supervisor.
const TemplateDescMaxRows = 0x8

// TemplateDescPrefixOff is the offset of prefix_off: u32 const, written by supervisor; the pre-rendered metadata bytes, within the registry.
const TemplateDescPrefixOff = 0xc

// TemplateDescPrefixLen is the offset of prefix_len: u32 const, written by supervisor.
const TemplateDescPrefixLen = 0x10

// TemplateDescBodyOff is the offset of body_off: u32 const, written by supervisor; from the start of the region.
const TemplateDescBodyOff = 0x14

// TemplateDescFrameCap is the offset of frame_cap: u32 const, written by supervisor; total bytes of the frame; constant for the template.
const TemplateDescFrameCap = 0x18

// TemplateDescFirstColumn is the offset of first_column: u32 const, written by supervisor.
const TemplateDescFirstColumn = 0x1c

// TemplateDescFirstPatch is the offset of first_patch: u32 const, written by supervisor.
const TemplateDescFirstPatch = 0x20

// TemplateDescPatchCount is the offset of patch_count: u16 const, written by supervisor.
const TemplateDescPatchCount = 0x24

// TemplateDescRowsFieldOff is the offset of rows_field_off: u32 const, written by supervisor; where the row count sits in the prefix.
const TemplateDescRowsFieldOff = 0x28

// Region column_desc (segment: registry).
const ColumnDescSize = 0x20

// ColumnDescValuesOff is the offset of values_off: u32 const, written by supervisor; from the start of the region.
const ColumnDescValuesOff = 0x0

// ColumnDescRowBytes is the offset of row_bytes: u32 const, written by supervisor.
const ColumnDescRowBytes = 0x4

// ColumnDescValidityOff is the offset of validity_off: u32 const, written by supervisor; 0 if non-nullable.
const ColumnDescValidityOff = 0x8

// ColumnDescNullCountOff is the offset of null_count_off: u32 const, written by supervisor; in the prefix; 0 if non-nullable.
const ColumnDescNullCountOff = 0xc

// ColumnDescListSize is the offset of list_size: u32 const, written by supervisor; 1 for scalars; N for FixedSizeList<T>[N]; the byte width for FIXED_BINARY.
const ColumnDescListSize = 0x10

// ColumnDescNameOff is the offset of name_off: u32 const, written by supervisor; into the names area.
const ColumnDescNameOff = 0x14

// ColumnDescNameLen is the offset of name_len: u16 const, written by supervisor.
const ColumnDescNameLen = 0x18

// ColumnDescElemType is the offset of elem_type: u8 const, written by supervisor.
const ColumnDescElemType = 0x1a

// ColumnDescNullable is the offset of nullable: u8 const, written by supervisor.
const ColumnDescNullable = 0x1b

// Region patch_desc (segment: registry).
const PatchDescSize = 0xc

// PatchDescPrefixOff is the offset of prefix_off: u32 const, written by supervisor; an 8-byte length field in the prefix.
const PatchDescPrefixOff = 0x0

// PatchDescScale is the offset of scale: u32 const, written by supervisor.
const PatchDescScale = 0x4

// PatchDescKind is the offset of kind: u8 const, written by supervisor.
const PatchDescKind = 0x8

