// ControlHeaderModelSha256 loads model_sha256 (bytes32, relaxed, written by supervisor).
func (s Seg) ControlHeaderModelSha256(base uintptr) (b [32]byte) {
	for i := uintptr(0); i < 4; i++ {
		v := s.ld64(base + ControlHeaderModelSha256 + i*8)
		for j := uintptr(0); j < 8; j++ {
			b[i*8+j] = byte(v >> (8 * j))
		}
	}
	return b
}

